        inputSchema: JSON.stringify(tool.inputSchema, null, 2),
      };

      if (isDeclarative) {
        declarativeResults.push({
          ...item,
          element,
        });
      } else {
        imperativeResults.push({
          ...item,
          source,
        });
      }
    }

    const list = [];

