      /** @type {LH.Audit.Details.Table['headings']} */
      const headings = [
        {key: 'tool', valueType: 'text', label: str_(UIStrings.columnTool)},
        {key: 'description', valueType: 'text', label: str_(UIStrings.columnDescription)},
        {key: 'source', valueType: 'source-location',
